css:
.gmm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.gmm-root,.gmm-root *,.gmm-root *::before,.gmm-root *::after{box-sizing:border-box}
.gmm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.gmm-root img{display:block;border:0;max-width:none}
.gmm-root > [data-node-id]{will-change:transform}
.gmm-root [hidden]{display:none!important}
.gmm-root [data-sh-theme="light"]{display:none!important}
.gmm-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.gmm-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.gmm-root .n34_1008{align-content:stretch;display:flex;gap:10px;align-items:center;position:relative;flex-shrink:0}
.gmm-root .n34_1009{align-content:stretch;display:flex;gap:6px;align-items:center;position:relative;flex-shrink:0}
.gmm-root .n34_1010{position:relative;border-radius:15.904px;flex-shrink:0;width:11px;height:11px;box-shadow:0px 0px 2.8px 0px white,0px 0px 2.8px 0px rgba(255,255,255,0.25);background-image:url("data:image/svg+xml;utf8,<svg viewBox='0 0 11 11' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'><rect x='0' y='0' height='100%' width='100%' fill='url(%23grad)' opacity='1'/><defs><radialGradient id='grad' gradientUnits='userSpaceOnUse' cx='0' cy='0' r='10' gradientTransform='matrix(0.38245 0.38245 -0.38245 0.38245 5.5 5.5)'><stop stop-color='color-mix(in srgb, var(--wa-bg, rgb(0 0 0)) 50%, transparent)' offset='0.475'/><stop stop-color='color-mix(in srgb, var(--wa-bg, rgb(16 16 16)) 53.13%, transparent)' offset='0.50781'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(32 32 32)) 56.25%, transparent)' offset='0.54062'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(64 64 64)) 62.5%, transparent)' offset='0.60625'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(96 96 96)) 68.75%, transparent)' offset='0.67187'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(128 128 128)) 75%, transparent)' offset='0.7375'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(159 159 159)) 81.25%, transparent)' offset='0.80312'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(191 191 191)) 87.5%, transparent)' offset='0.86875'/><stop stop-color='var(--wa-bg, rgba(255,255,255,1))' offset='1'/></radialGradient></defs></svg>"), linear-gradient(90deg, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent) 0%, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent) 100%)}
.gmm-root .n34_1010::after{content:"";position:absolute;inset:-0px;border:2px solid var(--wa-line, #fff);border-radius:15.904px;pointer-events:none}
.gmm-root .n34_1011{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:440;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:14px;color:var(--wa-text, #fff);white-space:nowrap;width:64px}
.gmm-root .n34_729{display:block;cursor:pointer;position:relative;flex-shrink:0;width:12px;height:12px}
.gmm-root .x34{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.gmm-root [data-name="Tab/GAS#1 (Active)"] + [data-name="Tab/GAS#1 (Active)"]{display:none!important}
.gmm-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.gmm-root[data-theme="light"] [data-name="Badge/Critical"] p,.gmm-root[data-theme="light"] [data-name^="status-critical"] p,.gmm-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.gmm-root[data-theme="light"] [data-name="Badge/Major"] p,.gmm-root[data-theme="light"] [data-name^="status-major"] p,.gmm-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #ad4d00)!important;font-weight:600;white-space:nowrap}
.gmm-root[data-theme="light"] [data-name="Badge/Minor"] p,.gmm-root[data-theme="light"] [data-name^="status-minor"] p,.gmm-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #856000)!important;font-weight:600;white-space:nowrap}
.gmm-root[data-theme="light"] [data-name="Badge/Warning"] p,.gmm-root[data-theme="light"] [data-name^="status-warning"] p,.gmm-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.gmm-root[data-theme="light"] [data-name="Badge/Normal"] p,.gmm-root[data-theme="light"] [data-name^="status-normal"] p,.gmm-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.gmm-root[data-theme="light"] [data-name^="Button/"]:not([data-name="Button/Close"]):not([data-name="Button/Ack"]) p{color:var(--wa-text, #fff)!important}
.gmm-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.gmm-root[data-theme="light"] .n34_1010{box-shadow:0px 0px 2.8px 0px white,0px 0px 2.8px 0px rgba(30,80,140,0.12);background-image:url("data:image/svg+xml;utf8,<svg viewBox='0 0 11 11' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'><rect x='0' y='0' height='100%' width='100%' fill='url(%23grad)' opacity='1'/><defs><radialGradient id='grad' gradientUnits='userSpaceOnUse' cx='0' cy='0' r='10' gradientTransform='matrix(0.38245 0.38245 -0.38245 0.38245 5.5 5.5)'><stop stop-color='color-mix(in srgb, var(--wa-bg, rgb(0 0 0)) 50%, transparent)' offset='0.475'/><stop stop-color='color-mix(in srgb, var(--wa-bg, rgb(16 16 16)) 53.13%, transparent)' offset='0.50781'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(32 32 32)) 56.25%, transparent)' offset='0.54062'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(64 64 64)) 62.5%, transparent)' offset='0.60625'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(96 96 96)) 68.75%, transparent)' offset='0.67187'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(128 128 128)) 75%, transparent)' offset='0.7375'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(159 159 159)) 81.25%, transparent)' offset='0.80312'/><stop stop-color='color-mix(in srgb, var(--wa-surface, rgb(191 191 191)) 87.5%, transparent)' offset='0.86875'/><stop stop-color='var(--wa-bg, rgba(255,255,255,1))' offset='1'/></radialGradient></defs></svg>"), linear-gradient(90deg, color-mix(in srgb, var(--wa-point, rgb(40 70 110)) 8%, transparent) 0%, color-mix(in srgb, var(--wa-point, rgb(40 70 110)) 8%, transparent) 100%)}
.gmm-root[data-theme="light"] .n34_1010::after{border-color:var(--wa-line, #3f5470)}
.gmm-root[data-theme="light"] .n34_1011{color:var(--wa-point, #15253a)}
